import * as A from './adapter';
import { type Emoji, type Person } from './model';
import {createFloatingPanel,PANEL_HOST} from './floating';
const documentId=crypto.randomUUID();
let busy=false;
let cancelled=false;
let interacted=false;
const interrupted=()=>{if(busy) interacted=true;};
// Trusted manual interaction cancels execution, but not clicks generated by this extension.
const isPanelEvent=(e:Event)=>e.composedPath().some(n=>n instanceof Element&&n.id===PANEL_HOST);
window.addEventListener('pointerdown',e=>{if(e.isTrusted&&!isPanelEvent(e)) interrupted();},true);
window.addEventListener('keydown',e=>{if(e.isTrusted&&!isPanelEvent(e)) interrupted();},true);
window.addEventListener('wheel',e=>{if(e.isTrusted&&!isPanelEvent(e)) interrupted();},true);
function guard() {
  if(cancelled) throw Error('任务已暂停');
  if(interacted) throw Error('检测到手动操作，任务已停止');
}
async function readOperation<T>(fn:()=>Promise<T>):Promise<T> {
  if(busy)throw Error('页面正在执行其他任务');
  busy=true;cancelled=false;interacted=false;
  try{return await fn();}finally{busy=false;}
}
async function panelApi(command:string,data:Record<string,unknown>={}) {
  try {
    const r=await chrome.runtime.sendMessage({type:'PANEL',command,data});
    if(!r?.ok)throw Error(r?.error||'扩展没有响应');return r.data;
  } catch(e) {
    if(/context invalidated|Receiving end does not exist|Could not establish connection/.test((e as Error).message)) throw Error('扩展已更新或连接失效，请刷新抖音聊天页');
    throw e;
  }
}
async function panelRead<T>(fn:()=>Promise<T>) {
  const token=await panelApi('READ_START');
  try{return await readOperation(fn);}finally{await panelApi('READ_END',{token}).catch(()=>{});}
}
let panel:ReturnType<typeof createFloatingPanel>|null=null;
function mountPanel() {
  if(!document.body)return;
  if(location.pathname!=='/chat'){panel?.destroy();panel=null;return;}
  if(panel?.host.isConnected)return;
  if(document.getElementById(PANEL_HOST))return;
  panel=createFloatingPanel({documentId,api:panelApi,
    scan:(progress,signal)=>panelRead(()=>A.scanPeople(guard,progress,signal)),
    emoji:()=>panelRead(()=>A.scanEmoji())
  });
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mountPanel,{once:true});else mountPanel();
// Douyin may navigate to /chat without a full document load.
setInterval(mountPanel,1500);
chrome.storage?.onChanged?.addListener((changes,area)=>{
  if(panel&&((area==='local'&&changes.state)||(area==='session'&&changes.binding)))void panel.refresh().catch(()=>{});
});
async function execute(payload:{person:Person;emoji:Emoji;account:string;documentId:string;dry?:boolean;runId?:string;deadline?:number}) {
  let attempted=false;
  let permit=false;
  let stage='检查页面和账号';
  const check=()=>{
    guard(); A.checkEnvironment();
    if(payload.deadline&&Date.now()>payload.deadline) throw Error('本次执行许可已超时');
    if(payload.documentId!==documentId) throw Error('页面已刷新，请重新绑定');
  };
  try {
    check();
    if(A.selfFingerprint()!==payload.account) throw Error('账号特征变化，请重新绑定');
    stage='打开并核对会话';
    await A.openPerson(payload.person,check);
    check();
    if(A.selfFingerprint()!==payload.account) throw Error('当前会话无法核对本人身份');
    if(!A.editorEmpty()) throw Error('会话中有草稿，已停止');
    stage='查找原生表情';
    const item=await A.findEmoji(payload.emoji,check);
    check(); A.assertPerson(payload.person);
    if(payload.dry) return {status:'ready',detail:`「${payload.person.name}」的会话身份与「${payload.emoji.name}」定位通过；未点击表情，未发送消息`};
    stage='申请发送许可';
    // Durable authorization is written by the worker immediately before a possible send.
    const response=await chrome.runtime.sendMessage({type:'PERMIT',runId:payload.runId,documentId});
    if(!response?.ok) throw Error(response?.error||'发送许可失效');
    permit=true;
    check(); A.assertPerson(payload.person);
    if(!A.editorEmpty()) throw Error('检测到新增草稿');
    const before=A.matchingMessages(payload.emoji);
    attempted=true;
    stage='触发表情';
    A.click(item.querySelector('img')||item);
    if(payload.emoji.kind==='small') {
      await A.until(()=>{
        check(); A.assertPerson(payload.person);
        // Native editors may represent a small emoji as an image or a text token.
        return !A.editorEmpty();
      },3000);
      check(); A.assertPerson(payload.person);
      // A small emoji inserts into the native editor; the send control sends it.
      A.click(A.one(A.S.send));
    }
    stage='核对新消息';
    const newMessage=await A.until(()=>{
      check(); A.assertPerson(payload.person);
      const after=A.matchingMessages(payload.emoji);
      return after.length>before.length ? after.find(e=>!before.includes(e)) : undefined;
    },6500);
    await A.delay(900);
    check(); A.assertPerson(payload.person);
    const flags=[...newMessage.querySelectorAll('[title],[aria-label]')].map(e=>(e.getAttribute('title')||'')+(e.getAttribute('aria-label')||'')).join(' ');
    if(/失败|重试|发送中/.test(flags)) throw Error('新消息仍在发送或显示失败，请人工核查');
    return {status:'observed',detail:'网页已出现匹配的本人表情消息；未验证服务器送达或续火结果'};
  } catch(e) {
    return {status:attempted?'uncertain':'failed',detail:`「${payload.person.name}」· ${stage}：${(e as Error).message}`,permit};
  } finally {
    // Never remove an uncertain draft or retry a potentially transmitted message.
    try { A.hidePanel(); } catch {}
  }
}
chrome.runtime.onMessage.addListener((message,sender,respond)=>{
  if(sender.id!==chrome.runtime.id) return;
  if(message.type==='CANCEL') { cancelled=true; respond({ok:true}); return; }
  if(message.type==='PING') {
    let account='',reason='';
    try{account=A.selfFingerprint();}catch(e){reason=(e as Error).message;}
    respond({ok:true,data:{documentId,account,reason,chat:location.pathname==='/chat',legacy:!!document.querySelector('#dy-fire-send')}});return;
  }
  if(!['PEOPLE','EMOJI','EXECUTE'].includes(message.type)) return;
  if(busy){respond({ok:false,error:'页面正在执行其他任务'});return;}
  busy=true;cancelled=false;interacted=false;
  (async()=>{
    if(message.type==='PEOPLE') return A.scanPeople(guard);
    if(message.type==='EMOJI') return A.scanEmoji();
    return execute(message.payload);
  })().then(data=>respond({ok:true,data}),e=>respond({ok:false,error:(e as Error).message})).finally(()=>{busy=false;});
  return true;
});
